    &\tup{\psX, \mathbf{t}, \mathbf{r}, \mathbf{f}} \mapsto \tup{
      \tup{\ps¬accounts', \ps¬stagingset', \ps¬authqueue', \ps¬privileges'}, \concatall{\mathbf{t}'}, \mathbf{b}, \mathbf{u}
    }\!\!\!\!\!\!\\
    &\text{where:}\\
    &\ \begin{aligned}
      \using &\tup{
        \ps¬accounts, \ps¬stagingset, \ps¬authqueue, \is{\ps¬privileges}{\tup{\pr¬manager, \pr¬delegator, \pr¬registrar, \pr¬assigners, \pr¬alwaysaccers}}
      } = \psX \\
      \mathbf{s} &= \set{\build{
        d_\wd¬serviceindex
        }{
          r \in \mathbf{r}, d \in r_\wr¬digests
        }} \cup \keys{\mathbf{f}} \cup \set{\build{t_\dx¬dest}{t \in \mathbf{t}}} \\
      N(\mathbf{o}) \in \acconeout &\equiv \tup{
        \ao¬poststate,
        \is{\ao¬modifiedaccounts}{\emset},
        \is{\ao¬defxfers}{\sq{}},
        \is{\ao¬yield}{\none},
        \is{\ao¬gasused}{\mathbf{o}_\ao¬gasused},
        \is{\ao¬provisions}{\mathbf{o}_\ao¬provisions}
      } \\
      \local¬acc(s) &\equiv \begin{cases}
        N(\mathbf{o}) &\when s \in \mathbf{o}_\ao¬modifiedaccounts \land s \in \mathbf{y}_\ao¬modifiedaccounts \setminus \set{\effectivesupervisor{\ps¬accounts}{s}} \\
        \mathbf{o} &\otherwise
      \end{cases} \\
      &\phantom{{}\equiv{}} \where \mathbf{o} = \accone(\psX, \mathbf{t}, \mathbf{r}, \mathbf{f}, s) \\
      &\phantom{{}\equiv{}} \also \mathbf{y} = \accone(\psX, \mathbf{t}, \mathbf{r}, \mathbf{f}, \effectivesupervisor{\ps¬accounts}{s}) \\
      \mathbf{u} &= \sq{\build{
          \tup{s, \local¬acc(s)_\ao¬gasused}
        }{
          s \orderedin \mathbf{s}
        }} \\
      \mathbf{b} &= \set{\build{
          \tup{s, b}
        }{
          s \in \mathbf{s},\,
          b = \local¬acc(s)_\ao¬yield,\,
          b \ne \none
        }} \\
      \mathbf{t}' &= \sq{\build{
          \local¬acc(s)_\ao¬defxfers
        }{
          s \orderedin \mathbf{s}
        }} \\
      \ps¬accounts' &= \local¬fnprovide(
        \mathbf{m} \cup \mathbf{n},
        \bigcup_{s \in \mathbf{s}} \local¬acc(s)_\ao¬provisions
      ) \\
      X(s) &\equiv (\local¬acc(s)_\ao¬poststate)_\ps¬privileges \\
      \ps¬privileges'_{\tup{\pr¬manager, \pr¬alwaysaccers}} &=
