        X(\pr¬delegator)_\pr¬delegator
      ) \\
      \ps¬privileges'_\pr¬registrar &= R(
        \pr¬registrar,
        X(m)_\pr¬registrar,
        X(\pr¬registrar)_\pr¬registrar
      ) \\
      \forall c \in \coreindex &:
        \ps¬privileges'_\pr¬assigners\subb{c} = R(
          \pr¬assigners\sub{c},
          (X(m)_\pr¬assigners)\sub{c},
          (X(\pr¬assigners\sub{c})_\pr¬assigners)\sub{c}
        ) \\
      \ps¬stagingset' &= (
        \local¬acc(\pr¬delegator)_\ao¬poststate
      )_\ps¬stagingset \\
      \forall c \in \coreindex &:
        \ps¬authqueue'\sub{c} = ((
          \local¬acc(\pr¬assigners\sub{c})_\ao¬poststate
        )_\ps¬authqueue)\sub{c} \\
      M(s) &\equiv \begin{cases}
        (\local¬acc(s)_\ao¬poststate)_\ps¬accounts\subb{s} &\when s \in \local¬acc(s)_\ao¬modifiedaccounts \\
        (\local¬acc(\effectivesupervisor{\ps¬accounts}{s})_\ao¬poststate)_\ps¬accounts\subb{s} &\otherwise
