      \mathbf{m} &= \set{\build{\kv{s}{M(s)}}{s \in \keys{\ps¬accounts}, M(s) \ne \none}} \\
      \mathbf{n} &= \bigcup_{s \in \mathbf{s}}(
        (\local¬acc(s)_\ao¬poststate)_\ps¬accounts
          \setminus
        \keys{\ps¬accounts}
      )
    \end{aligned}
  \end{aligned}}

